		org	$ad000;----------------------------------------------------------------------;;	PLINKC ver 1.64 -- el buffer de escritura se vuelca solo;	update by PHOENIX, 2026;;	Pocket Link Cache Device Driver ver 1.62;	Installation program;	for PC-E500 series pocket computer;	Copyright (c) 1996,1997,1999 by Daisuke Mizobata;;----------------------------------------------------------------------;;----------------------------------------------------------------------;		各種数値定義;----------------------------------------------------------------------fcs:		equ	$fffe4iocs:		equ	$fffe8iocs_fook:	equ	$bfca2sio_rcv_vct:	equ	$bfcd5sio_param:	equ	$bfd33base:		equ	$ecbx:		equ	$d4cx:		equ	$d6cl:		equ	$d6ch:		equ	$d7dx:		equ	$d8key_strobe_2:	equ	$f1sio_ctrl_reg:	equ	$f7sio_stat_reg:	equ	$f8sio_rx_reg:	equ	$f9sio_tx_reg:	equ	$faintr_mask_reg:	equ	$fbsystem_stat_reg:equ	$ffbtext:	equ	$cbbdata:	equ	$cebpmax:	equ	$caiwork:	equ	$e6keyvec:	equ	$bfc41s1top:	equ	$bfc15s1end:	equ	$bfcdecdrv:	equ	$bfc7drev:	equ	$bfca1iroot:	equ	$bfca2bworkp:	equ	$bfd0esectsiz:	equ	128cache_sect:	equ	sectsiz+1cache_next:	equ	cache_sect+2cache_size:	equ	cache_next+3n_fcache:	equ	7		;	FATキャッシュのセクタ数n_dcache:	equ	1		;	データーキャッシュのセクタ数dtop:		equ	44timeout:	equ	40000		;	タイムアウト時間(約1秒)#DEFMACRO bsr	call	%0#ENDMACRO;;	インストーラー;pntr	dest,bottom,mdf,offsetentry:	pre	$32	sub	($ec),%	mv	il,title-mb	call	putm2;	既に"L:"が存在するか	mv	x,dvname	mv	il,0	call	icall		;	ドライブ名のサーチ	mv	il,exi_m-mb	jpnc	msend	mv	y,[iroot]	;	もとのIOCSヘッダリストの先頭	mv	[ihead],y;	デバイスナンバーを設定	pre	$32	mv	(cx),10-1	;	デバイスナンバー10を予定	{		pre	$32		inc	(cx)		mv	il,1		call	icall		jrnc	continue	}	pre	$32	mv	[devno],(cx)	;	デバイスナンバーを設定;	IOCSリストに登録（固定番地なので再配置も移動も不要）	mv	x,ihead	mv	[iroot],x	mv	x,dvname	mv	il,$04	call	icall		;	パラメタの初期化	mv	il,ins_m-mbmsend:	call	putm2	pre	$32	add	($ec),%	retfputm2:	mv	x,mb	add	x,i	mv	il,[x++]	mv	y,i	pre	$32	mv	(cx),0	mv	il,$04	callf	fcs	retlinkbas:;	BTEXT$とBDATA$のポインタを張り直す	pre	$32	mv	x,[bworkp]	mv	a,$72	add	x,a	call	bsearch	jrc	bomb	pre	$32	mv	(btext),y	call	bsearch	jrc	bomb	pre	$32	mv	(bdata),y	retbomb:	resetbsearch:mv	il,$41memd2:	pre	$32	mv	(cx+1),[x++]memd:	pre	$32	mv	(cx),6icall:	callf	iocs	retmb:title:	db	37+34,'PLINKC ver 1.62 by Daisuke Mizobata',$0d,$0a	db	'based on PLINK ver 1.04 by N.Kon',$0d,$0aexi_m:	db	17,'Already exists.',$0d,$0amem_m:	db	20,'Not enough memory.',$0d,$0ains_m:	db	12,'Installed.',$0d,$0apg_m:	db	17,'Over two pages.',$0d,$0a;----------------------------------------------------------------------;		デバイスドライバのファイルヘッダ;----------------------------------------------------------------------btop:		db	$fb,'PLINK   SYS'	;デバイスブロック名		db	$25			;メモリブロックの属性		dw	0,0			;日付と時間		dp	blen			;メモリブロックのバイト数		dw	0		dp	blen			;ファイル実体のバイト数		dp	blen			;メモリブロックのバイト数		dp	0,0;----------------------------------------------------------------------;		デバイスドライバのヘッダ;----------------------------------------------------------------------ihead:		dp	0		;次のデバイスドライバヘッダのアドレスdevno:		db	0		;デバイスナンバ（可変）		db	$83		;デバイスの属性（Ｅ：と同じ）		dp	devmain		;デバイスドライバ本体のアドレスdvname:		db	'L:',0		;デバイス名;----------------------------------------------------------------------;		Media parameter block;----------------------------------------------------------------------;128KB版mpb128:		db	$f0		;メディアディスクリプタ（適当でよい）		dw	sectsiz		;１セクタのバイト数		db	4-1		;(１セクタのバイト数/32) -1		db	2		;log2 (１セクタのバイト数/32)		db	0		;???		db	1		;???		dw	0		;ＦＡＴエリアの先頭セクタ番号		db	8		;???		dw	128		;最大収容可能ファイル数		dw	dtop		;ＤＡＴＡエリアの先頭セクタ番号		dw	980+1		;ＤＡＴＡエリアの総セクタ数+1		db	12		;ＦＡＴエリアの総セクタ数		dw	12		;ＤＩＲエリアの先頭セクタ番号;DSで参照するデータ		dw	12		;ＤＩＲエリアの先頭セクタ番号;512KB版mpb512:		db	$f0		dw	sectsiz		db	4-1		db	2		db	0		db	1		dw	0		db	8		dw	128		dw	80		;ＤＡＴＡエリアの先頭セクタ番号		dw	4016+1		;ＤＡＴＡエリアの総セクタ数+1		db	48		;ＦＡＴエリアの総セクタ数		dw	48		;ＤＩＲエリアの先頭セクタ番号;		dw	48;----------------------------------------------------------------------;		本体;----------------------------------------------------------------------suborg		0byte		i_work1,i_work2word		sect_num,sect_num2byte		flag,rxdata,i_work3,subkopntr		cachep,vct_rsv,beforedevmain:	pushu	imr		;割り込みを止めてＳＩＯ受信ベクタを書き替える		pushu	x		pre	$30		sub	(base),%		mv	x,[sio_rcv_vct]		mv	(vct_rsv),x			mv	x,rcv		mv	[sio_rcv_vct],x		popu	x		popu	imr		mv	(i_work3),[sio_param]   ;設定内容読み込み		and	(i_work3),$fd	   	;これで強制８ビット化		pre	$22		ex	(i_work3),(sio_ctrl_reg);ＳＩＯの設定＆以前の内容保存		pre	$22		mv	(subko),(key_strobe_2)	;KOHを保存する		pre	$30		or	(key_strobe_2),$60	;ＤＴＲ、ＲＲをＯＮにする;		bsr	main;		{			pre	$30			test	(sio_stat_reg),$10			jrz	continue	;送信終了まで待つ		}		pre	$30		mv	(sio_ctrl_reg),(i_work3);ＳＩＯパラメタを元に戻す		pre	$30		mv	(key_strobe_2),(subko)	;KOHを元に戻す		test	(flag),2		jrz	jump00			;［ＢＲＫ］は押されていたか？		mv	a,$02		jrc	jump00brkloop:	test	[$bfcbe],$80		;Breakが離されるまで待つ		jrnz	brkloop		mv	a,$ff			;押されていたときの処理		scjump00:		pushu	imr			;ＳＩＯ受信ベクタを元に戻す		pushu	x		mv	x,(vct_rsv)		mv	[sio_rcv_vct],x		pre	$30		pmdf	(base),%		popu	x		popu	imr		retf;----------------------------------------------------------------------;		各種コマンド;----------------------------------------------------------------------init:		mv	a,[x]		cmp	a,'1'		jrnz	cmd3f_5		mv	x,mpb128		jr	cmd3f_15cmd3f_5:	cmp	a,'5'		jrnz	cmd3f_d		mv	x,mpb512cmd3f_15:	pushu	a		mv	[getmpb+1],x		mv	ba,[x+$c]		mv	[secpatch+1],ba		bsr	check_sect		mv	a,'S'		bsr	send_one		popu	a		bsr	send_one		jr	cmd3f_2cmd3f_d:	cmp	a,'D'		jrnz	cmd3f_i		bsr	check_sect	;”Ｄ”コマンド		mv	a,'D'		bsr	send_one	;”Ｄ”コマンドを送る		mv	i,$12+(receive_one_s-receive_one-2)*$100		mv	[receive_one],i	;jr receive_one_s		jr	cmd3f_2cmd3f_i:	cmp	a,'I'		jrnz	cmd3f_2		mv	il,130		;”Ｉ”コマンド		mv	a,0		;００ｈを１３０個送信するcmd3f_i1:	bsr	send_one		dec	il		jrnz	cmd3f_i1cmd3f_2:	bsr	buffer_clr	;バッファをきれいにする		;bsr	root		;retroot:		bsr	getroot			mv	[x+$a],i		mv	[x+$11],ba		rc		retgetroot:	bsr	getmpb		mv	ba,[x+$13]		mv	il,128		retgetmpb:		mv	x,mpb128		rc		ret;----------------------------------------------------------------------;		各処理の本体;----------------------------------------------------------------------main:		mv	(flag),0	;フラグをクリアする		mv	a,il		;コマンド解析;----------------------------------------------------------------------;	Volcado automatico del buffer de escritura;----------------------------------------------------------------------;	Con la orden $17 BASIC pide un puntero a sect_1 y escribe DENTRO; el;	driver no se entera de cuando ha terminado.  Cualquier otra orden;	significa que ya acabo, asi que se expulsa lo pendiente.;	  - se salvan ba/i/x/y porque volcar los machaca y $12-$15 usan x;	    (la 'a' del despacho vuelve con ba, del que es el byte bajo);	  - sect_number = -1 significa que aun no hay sector cargado: sect_1;	    seria RAM sin inicializar y se mandaria basura		cmp	a,$17		jrz	nv_ya		pushu	ba		pushu	i		pushu	x		pushu	y		mv	ba,[sect_number]		inc	ba		jrz	nv_fin		bsr	volcarnv_fin:		popu	y		popu	x		popu	i		popu	ba		mv	(flag),0nv_ya:		cmp	a,$10		jrnz	cmd11		rc			;コマンド１０ｈの処理		retcmd11:		cmp	a,$11		jrz	getmpb		;コマンド１１ｈの処理		cmp	a,$12		jrz	read_sect	;コマンド１２ｈの処理		cmp	a,$13		jrz	write_sect	;コマンド１３ｈの処理		cmp	a,$14		jrz	write_sect	;コマンド１４ｈの処理		cmp	a,$15		jrz	read_sect	;コマンド１５ｈの処理		cmp	a,$16		jrnz	cmd17		mv	ba,0		;コマンド１６ｈの処理		rc		retcmd17:		cmp	a,$17		jrnz	cmd18		mv	ba,[sect_number]	;コマンド１７ｈの処理		pre	$30		cmpw	(bx),ba		jrz	same_sect	;バッファと同じセクタだった		bsr	check_sect		test	(flag),2		jrnz	cmd17_err		pre	$30		mv	ba,(bx)		mv	[sect_number],ba		mv	(sect_num),ba		mv	x,sect_1		mv	y,sect_2	;コピーも作る		mv	il,sectsiz/2+1		bsr	rcv_sect	;指定セクタを読み込む		test	(flag),2		jrz	same_sect		mv	ba,-1		mv	[sect_number],ba		jr	cmd17_errsame_sect:	pre	$30		mvw	(cx),sectsiz		mv	x,sect_1		rccmd17_err:	retcmd18:		cmp	a,$18		jrz	getroot		;コマンド$18の処理（DS用）	cmd3f:		cmp	a,$3f		jrz	init		;コマンド３Ｆｈの処理cmd40:		cmp	a,$40		jrz	root		;コマンド４０ｈの処理cmd_err:	mv	a,3		;無効なコマンド		sc		ret;----------------------------------------------------------------------;		セクタの連続読み込み;----------------------------------------------------------------------read_sect:	pre	$22		mvw	(sect_num),(bx)		mv	y,x		mv	il,sectsiz/2		mv	ba,[sect_number]		cmpw	(sect_num),ba    ;バッファリングしているセクタと		jrnz	read_sect1	    ;ヒットしたか？		mv	y,sect_1read_sect2:	mv	ba,[y++]		mv	[x++],ba		dec	il		jrnz	read_sect2		jr	read_sect3read_sect1:	bsr	rcv_sect		test	(flag),2		jrnz	read_errread_sect3:	pre	$30		mv	ba,(bx)		inc	ba		pre	$30		mv	(bx),ba		pre	$30		mv	ba,(dx)		dec	ba		pre	$30		mv	(dx),ba		jrnz	read_sect		rcread_err:	ret;----------------------------------------------------------------------;		セクタの連続書き込み;----------------------------------------------------------------------write_sect:	pre	$22		mvw	(sect_num),(bx)		mv	il,sectsiz		mv	ba,[sect_number]		cmpw	(sect_num),ba    ;バッファリングしているセクタと		jrnz	write_sect1	    ;ヒットしたか？		mv	y,sect_1write_sect2:	mv	a,[x++]		mv	[y++],a		dec	il		jrnz	write_sect2		jr	write_sect3write_sect1:	bsr	send_sect		test	(flag),2		jrnz	write_errwrite_sect3:	pre	$30		mv	ba,(bx)		inc	ba		pre	$30		mv	(bx),ba		pre	$30		mv	ba,(dx)		dec	ba		pre	$30		mv	(dx),ba		jrnz	write_sect		rcwrite_err:	ret;----------------------------------------------------------------------;		１セクタ送信;----------------------------------------------------------------------send_sect:	pushu	il		bsr	send_cache	;ＣＡＣＨＥの処理		popu	il		pushu	imr		pre	$30		mv	(intr_mask_reg),$a0		mv	y,(cachep)		pushu	ysend_sect_2:	mv	a,[x++]		mv	[y++],a		;ＣＡＣＨＥへ書き込む		dec	il		jrnz	send_sect_2		mv	a,'W'		bsr	send_one	;書き込むコマンド送信		mv	a,(sect_num)		bsr	send_one	;セクタ番号の下位１バイト送信		mv	a,(sect_num+1)		bsr	send_one	;セクタ番号の上位１バイト送信		popu	y		mv	il,sectsiz+1send_sect_3:	mv	a,[y++]		bsr	send_one	;１２９バイトのＣＡＣＨＥデータを送信		dec	il		jrnz	send_sect_3		mv	a,$ff		bsr	send_one	;正常終了の印を送信		bsr	receive_one		test	(flag),2		jrz	send_ok		mv	ba,-1		mv	[y],ba		;送信中止したキャッシュを無効にするsend_ok:	popu	imr		ret;----------------------------------------------------------------------;		１セクタ受信;----------------------------------------------------------------------rcv_sect:	pushu	imr		pushu	il		pre	$30		mv	(intr_mask_reg),$a0		bsr	send_cache	;ＣＡＣＨＥの処理		popu	il		jrnc	read_cache	;ＣＡＣＨＥから読めばよいときジャンプ		pushu	il		pushu	x		mv	x,(cachep)	;ＣＡＣＨＥに読み込む		mv	a,'R'		bsr	send_one	;読みだしコマンド送信		mv	a,(sect_num)		bsr	send_one	;セクタ番号の下位１バイト送信		mv	a,(sect_num+1)		bsr	send_one	;セクタ番号の上位１バイト送信		rc		bsr	receive_one	;(セクタサイズ+1)バイト受信		jrc	rcv_sect_2		mv	[x++],a		mv	il,sectsizrcv_sect_1:	bsr	receive_one		mv	[x++],a		dec	il		jrnz	rcv_sect_1rcv_sect_2:	popu	x		popu	ilread_cache:	mv	[--s],u		;ＣＡＣＨＥから読み込む		mv	u,(cachep)		test	(flag),2		jrz	read_cache_1		mv	ba,-1		mv	[u+cache_sect],ba;受信中止したキャッシュを無効にする		jr	rcv_errread_cache_1:	popu	ba		;mv	ba,[u++]		mv	[x++],ba		mv	[y++],ba		dec	il		jrnz	read_cache_1rcv_err:	mv	u,[s++]		popu	imr		ret;----------------------------------------------------------------------;		１バイト送信;----------------------------------------------------------------------send_one:	pre	$30		test	(sio_stat_reg),$8		jrz	send_one	;Tx ready になるまで待つ		test	(flag),2		jrz	send_one_2	;送信中止モードなら００ｈを送信することになる		mv	a,0send_one_2:	pre	$30		mv	(sio_tx_reg),a	;送信		ret;----------------------------------------------------------------------;		１バイト受信;----------------------------------------------------------------------receive_one:	jr	receive_one_s		db	system_stat_reg,8;		test	(system_stat_reg),8		jrnz	receive_one_err	;［ＢＲＫ］が押された		test	(flag),1		jrz	receive_one	;１バイト受信するまで待つ		mv	a,(rxdata)		and	(flag),$fe	;フラグをリセットする		retreceive_one_s:	mv	ba,timeoutreceive_one_lp:	pre	$30			;1		test	(system_stat_reg),8	;4		jrnz	receive_one_err		;2		test	(flag),1		;4		jrnz	receive_one_ok		;2		dec	ba			;3		jrnz	receive_one_lp		;3		screceive_one_err:or	(flag),2	;送信中止モードにする		retreceive_one_ok:	mv	ba,$6530	;pre $30 test (m),n		mv	[receive_one],ba		mv	a,(rxdata)		and	(flag),$fe	;フラグをリセットする		ret;----------------------------------------------------------------------;		受信割込み処理ルーチン;----------------------------------------------------------------------rcv:		pre	$30		mv	a,(sio_rx_reg)		mv	(rxdata),a		or	(flag),1	;受信完了フラグを立てる		retf;----------------------------------------------------------------------;		バッファ・クリア;----------------------------------------------------------------------buffer_clr:	mv	il,sectsiz+2		mv	ba,0		mv	x,sect_1buffer_clr_1:	mv	[x++],ba		;バッファを００ｈで埋める		dec	i		jrnz	buffer_clr_1		mv	ba,-1		mv	[sect_number],ba	;セクタ番号の初期化		mv	il,n_fcache		mv	y,fcache		mv	[fcachep],y		bsr	buffer_clr_3		;FATキャッシュの初期化		mv	il,n_dcache		mv	y,dcache		mv	[dcachep],y		bsr	buffer_clr_3		;データキャッシュの初期化		retbuffer_clr_3:	mv	x,y		mv	[x+cache_sect],ba		dec	il		jrz	buffer_clr_2		mv	ba,cache_size		add	y,ba		mv	[x+cache_next],y		jr	buffer_clr_3buffer_clr_2:	mv	y,$fffff		mv	[x+cache_next],y		ret;----------------------------------------------------------------------;		コマンド$17用のバッファの一致検査;----------------------------------------------------------------------;----------------------------------------------------------------------;		Volcar sect_1 dejando los buffers al dia;----------------------------------------------------------------------;	check_sect expulsa sect_1 si difiere de sect_2, pero NO actualiza;	sect_2: en el original siempre le sigue una lectura que rellena los;	dos a la vez.  Aqui no la hay, asi que hay que igualarlos o la;	siguiente orden volveria a mandar el mismo sector, y la siguiente.volcar:		bsr	check_sect;	si el envio fallo (BRK o timeout) NO se igualan los buffers: hay que;	dejarlos distintos para que la siguiente orden lo vuelva a intentar,;	o se daria por volcado algo que nunca llego al servidor		test	(flag),2		jrnz	volcar_fin		mv	x,sect_1		mv	y,sect_2		mv	il,sectsiz+1volcar_1:	mv	a,[x++]		mv	[y++],a		dec	il		jrnz	volcar_1volcar_fin:	retcheck_sect:	mv	x,sect_1		mv	il,sectsiz+1check_sect_3:	mv	(i_work1),[x++]		mv	a,[x+sectsiz+1]		cmp	(i_work1),a	;バッファ内容の比較		jrnz	check_sect_4		dec	il		jrnz	check_sect_3		retcheck_sect_4:		mvw	(sect_num),[sect_number]		mv	x,sect_1		mv	il,sectsiz+1		pushu	x		bsr	send_sect	;バッファを追い出す		popu	x		mv	ba,(sect_num)		inc	ba		mv	(sect_num),ba		dec	ba		dec	ba		mv	(sect_num2),ba		mv	y,(cachep)check_sect_6:	mv	ba,[y+cache_sect]		cmpw	(sect_num),ba		jrnz	check_sect_5		pushu	a		mv	a,[x+sectsiz]		mv	[y],a		;アクセスしたセクタの次のセクタの1バイト目		popu	acheck_sect_5:	cmpw	(sect_num2),ba		jrnz	check_sect_7		mv	a,[x]		mv	[y+sectsiz],a	;アクセスしたセクタの前のセクタの129バイト目check_sect_7:	mv	y,[y+cache_next]		pushu	y		inc	y		popu	y		jrnz	check_sect_6		ret;----------------------------------------------------------------------;		Cacheとの一致検査;----------------------------------------------------------------------send_cache:		pushu	x		pushu	y		mv	x,dcachepsecpatch:	mv	ba,dtop		;DATAエリアの先頭セクタ番号が書き込まれる		cmpw	(sect_num),ba		jrnc	send_cache_0		mv	x,fcachepsend_cache_0:	mv	(cachep),x		mv	(before),x		mv	x,[x]send_cache_1:	mv	ba,[x+cache_sect]		mv	y,[x+cache_next]		cmpw	(sect_num),ba		jrz	send_cache_2	;アクセスしようとしたセクタはＣＡＣＨＥと同じ		pushu	y		inc	y		popu	y		sc			;ＣＡＣＨＥからは読み込めないという印		jrz	send_cache_2		mv	a,cache_next		add	x,a		mv	(before),x		mv	x,y		jr	send_cache_1send_cache_2:	mv	[(before)],y		mv	y,[(cachep)]		mv	[x+cache_next],y		mvw	[x+cache_sect],(sect_num)		mv	[(cachep)],x		mv	(cachep),x		popu	y		popu	x		retprgend:;----------------------------------------------------------------------;		ワークエリア;----------------------------------------------------------------------suborg		*byte		sect_1[sectsiz+1+1],sect_2[sectsiz+1+1]pntr		fcachep,dcachepbyte		fcache[cache_size*n_fcache]byte		dcache[cache_size*n_dcache]word		sect_numberblen:		equ	%-btop		end